function nextGreaterImpl(nums) {
  const result=new Array(nums.length).fill(-1),stack=[];
  for(let i=0;i<nums.length;i++){
    while(stack.length&&nums[stack[stack.length-1]]<nums[i])result[stack.pop()]=nums[i];
    stack.push(i);
  }
  return result;
}

function dailyTemperaturesImpl(temperatures) {
  const result=new Array(temperatures.length).fill(0),stack=[];
  for(let i=0;i<temperatures.length;i++){
    while(stack.length&&temperatures[stack[stack.length-1]]<temperatures[i]){
      const idx=stack.pop();result[idx]=i-idx;
    }
    stack.push(i);
  }
  return result;
}

function largestRectangleAreaImpl(heights) {
