function nextGreaterElementsImpl(nums) {
  const n=nums.length,result=new Array(n).fill(-1),stack=[];
  for(let i=0;i<2*n;i++){
    const val=nums[i%n];
    while(stack.length&&nums[stack[stack.length-1]]<val)result[stack.pop()]=val;
    if(i<n)stack.push(i);
  }
  return result;
}

function nextGreaterElementImpl(nums1,nums2){
  const map=new Map(),stack=[];
  for(const num of nums2){
    while(stack.length&&stack[stack.length-1]<num)map.set(stack.pop(),num);
    stack.push(num);
  }
  return nums1.map(n=>map.get(n)??-1);
}

