function sumSubarrayMinsImpl(arr) {
  const MOD=1e9+7,n=arr.length,left=new Array(n),right=new Array(n);
  const s1=[];
  for(let i=0;i<n;i++){
    while(s1.length&&arr[s1[s1.length-1]]>=arr[i])s1.pop();
    left[i]=s1.length?i-s1[s1.length-1]:i+1;
    s1.push(i);
  }
  const s2=[];
  for(let i=n-1;i>=0;i--){
    while(s2.length&&arr[s2[s2.length-1]]>arr[i])s2.pop();
    right[i]=s2.length?s2[s2.length-1]-i:n-i;
    s2.push(i);
  }
  let result=0;
  for(let i=0;i<n;i++)result=(result+arr[i]*left[i]*right[i])%MOD;
  return result;
}

