function minSlidingWindowImpl(nums, k) {
  const dq=[],r=[];
  for(let i=0;i<nums.length;i++){
    if(dq.length&&dq[0]<i-k+1)dq.shift();
    while(dq.length&&nums[dq[dq.length-1]]>=nums[i])dq.pop();
    dq.push(i);
    if(i>=k-1)r.push(nums[dq[0]]);
  }
  return r;
}

function constrainedSubsetSumImpl(nums, k) {
  const n=nums.length,dp=[...nums],dq=[0];
  for(let i=1;i<n;i++){
    if(dq[0]<i-k)dq.shift();
    dp[i]=nums[i]+Math.max(0,dp[dq[0]]);
    while(dq.length&&dp[dq[dq.length-1]]<=dp[i])dq.pop();
    dq.push(i);
  }
  return Math.max(...dp);
}

